const Item = (props: { item: Blog, onclick?: (item: Blog) => void }) => {
  const { item, onclick } = props;

  return (
    <Stack
      flex={1}
      borderRadius={2}
      component={Link}
      href={StringFormat(NEW_DETAIL_PATH, { slug: item.slug })}
      onClick={() => {
        if (onclick) onclick(item)
      }}
      border="1px solid"
      borderColor="divider"
      bgcolor="background.paper"
      overflow="hidden"
      sx={{
        "&:hover": {
          "& .follow": {
            display: "flex",
          },
          "& img": {
            transition: "transform 0.3s ease-in-out",
            transform: "scale(1.1)",
          },
        },
        maxWidth: "100%"
      }}
    >
      <Stack position="relative" width="100%" sx={{ aspectRatio: 16 / 9 }}>
        <Image
          src={item.thumbnailUrl}
          aspectRatio={16 / 9}
          size="100%"
          sizes="200px"
          containerProps={{
            borderRadius: 1,
            overflow: "hidden",
            bgcolor: "grey.500",
          }}
        />
      </Stack>

      <Stack p={2} pt={1} spacing={1} minWidth={0} justifyContent={'space-between'} height={'100%'}>
        <Stack spacing={1}>
          <Text lineHeight={"100%"} variant={'caption'} fontWeight={600} color="grey.400">
            {formatDate(item.publicDate)}
          </Text>
          <Text variant="h6">{item.title}</Text>
          <Text
            variant="body2"
            color="grey.400"
            sx={{
              display: "-webkit-box",
              WebkitLineClamp: 2,
              WebkitBoxOrient: "vertical",
              overflow: "hidden",
              textOverflow: "ellipsis",
            }}
          >
            {item.metaDescription}
          </Text>
        </Stack>
        <Stack
          direction={'row'}
          gap={1}
          alignItems={'center'}
          onClick={(e) => {
            e.stopPropagation();
            e.preventDefault();
          }}
        >
          {item?.tags?.slice(0, MAX_TAGS)?.map((tags, i) => {
            return <Chip
              title={tags}
              key={i}
              fontSize={12}
              fontWeight={500}
            // onclick={() => {
            //   if (onclick) {
            //     onclick(tags)
            //   }
            // }}
            />
          })}

          {item?.tags?.length > MAX_TAGS &&
            <Chip
              title={`+${item?.tags?.length - MAX_TAGS}`}
              remainingTags={item.tags.slice(MAX_TAGS)}
              fontSize={12}
              fontWeight={500}
            />
          }
        </Stack>
      </Stack>
    </Stack>
  );
};

